window.ProjectOverview=(()=>{
 function render(data,{today,date,avatar}){
  const m=ProjectDashboard.model(data,today),p=m.p,atRisk=m.open.filter(t=>['High','Critical'].includes(t.priority)),colors={Done:'#18aa79','In Progress':'#328cff',Review:'#9272d5',Todo:'#95a9c2',Backlog:'#c0cad7'};
  const dates=[p.startDate,p.endDate,...m.tasks.flatMap(t=>[t.startDate,t.endDate]),...m.checkpoints.map(x=>x.date)].filter(Boolean).sort(),start=Planning.day(dates[0]),end=Planning.day(dates.at(-1)),days=Math.max(1,end-start+1);
  const ticks=Array.from({length:6},(_,i)=>date(Planning.iso(start+Math.floor(days*i/6))));
  const left=d=>(Planning.day(d)-start)/days*100,width=(a,b)=>Math.max(.7,(Planning.day(b)-Planning.day(a)+1)/days*100);
  const phases=[...new Set(['Discovery','Design','Development','Launch',...m.tasks.map(t=>t.phase||'Other')])].filter(phase=>m.tasks.some(t=>(t.phase||'Other')===phase));
  const row=(t,i)=>`<div class="po-plan-row"><div class="po-task-meta"><small>${i}</small><button class="task-title" data-bug-edit="${esc(t.id)}" title="${esc(ProjectAPI.ticketKey(t)+' · '+t.name)}">${esc(t.name)}</button><div class="po-task-owner">${avatar(data.members.find(x=>x.id===t.assigneeId))}</div><span class="po-status"><i style="background:${colors[t.status]}"></i>${esc(t.status)}</span></div><div class="po-track"><button class="po-bar" data-bug-edit="${esc(t.id)}" aria-label="Edit ${esc(ProjectAPI.ticketKey(t)+' '+t.name)}" title="${esc(t.name)} · ${esc(t.startDate)} – ${esc(t.endDate)}" style="left:${left(t.startDate)}%;width:${width(t.startDate,t.endDate)}%;background:${colors[t.status]}"></button></div></div>`;
  const chart=phases.map((phase,index)=>{const tasks=m.tasks.filter(t=>(t.phase||'Other')===phase),sorted=[...tasks].sort((a,b)=>a.startDate.localeCompare(b.startDate)),finish=tasks.map(t=>t.endDate).sort().at(-1);return `<details class="po-work-package" open><summary><div class="po-task-meta"><small>${index+1}</small><strong>${esc(phase)}</strong><span></span><small>${Planning.progress(tasks)}%</small></div><div class="po-track"><i class="po-bar po-group-bar" style="left:${left(sorted[0].startDate)}%;width:${width(sorted[0].startDate,finish)}%"></i></div></summary>${sorted.map((t,i)=>row(t,`${index+1}.${i+1}`)).join('')}</details>`}).join('');
  let angle=0;const stops=m.counts.filter(c=>c.count).map(c=>{const from=angle;angle+=c.count/Math.max(1,m.tasks.length)*100;return `${colors[c.status]} ${from}% ${angle}%`}).join(',');
  return `<div class="po-dashboard"><div class="po-main"><div class="po-breadcrumb"><button class="text-btn" data-all-projects>Projects</button><span>›</span><label class="sr-only" for="dashboard-project">Current project</label><select id="dashboard-project">${data.projects.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="po-title"><span class="po-project-icon"><span class=\"fa-solid fa-calendar-days\" aria-hidden=true></span></span><div><h1>${esc(p.name)}</h1><p>${esc(p.description||'Add a project description to share the scope and objectives.')}</p></div><div class="po-actions"><button class="primary" data-project-new-task="${esc(p.id)}">+ Add Task</button><button class="secondary" data-project-edit="${esc(p.id)}">Edit Project</button><button class="secondary" data-refresh-project aria-label="Refresh project"><span class=\"fa-solid fa-rotate-right\" aria-hidden=true></span></button></div></div><div class="po-meta"><div><span>Start Date</span><b>${esc(p.startDate)}</b></div><div><span>End Date</span><b>${esc(p.endDate)}</b></div><div><span>Delivery health</span><b class="po-health ${m.overdue.length?'po-needs-attention':''}">${esc(m.health)}</b></div><div><span>Overall Progress</span><div class="po-progress"><b>${m.progress}%</b><i><em style="width:${m.progress}%"></em></i></div></div></div><section class="po-kpis">${[['<span class=\"fa-solid fa-file-lines\" aria-hidden=true></span>','Total Tasks',m.tasks.length,`${m.done} completed`,'blue'],['<span class=\"fa-solid fa-circle-check\" aria-hidden=true></span>','Completed',m.done,`${m.progress}%`,'green'],['<span class=\"fa-solid fa-clock\" aria-hidden=true></span>','In Progress',m.counts.find(c=>c.status==='In Progress').count,'Currently underway','blue'],['<span class=\"fa-solid fa-triangle-exclamation\" aria-hidden=true></span>','At Risk',atRisk.length,'High / critical open tasks','orange'],['<span class=\"fa-solid fa-calendar-xmark\" aria-hidden=true></span>','Overdue',m.overdue.length,'Open tasks past due','red']].map(([icon,label,value,sub,color])=>`<div class="po-kpi ${color}"><i>${icon}</i><div><span>${label}</span><strong>${value}</strong><small>${sub}</small></div></div>`).join('')}</section><section class="panel po-plan"><div class="po-panel-heading"><h2>Project Plan (Gantt Chart)</h2><div><button class="text-btn po-view-active" data-project-gantt="${esc(p.id)}">Gantt ↗</button><button class="text-btn" data-project-plan="${esc(p.id)}">List</button><button class="text-btn" data-project-board="${esc(p.id)}">Board</button></div></div><div class="po-plan-scroll" tabindex="0" aria-label="Project plan chart, scroll horizontally to see the schedule"><div class="po-plan-canvas" style="--today:${left(today)}%;--today-display:${Planning.day(today)>=start&&Planning.day(today)<=end?'block':'none'}"><div class="po-plan-row po-plan-head"><div class="po-task-meta"><span>ID</span><span>Task Name</span><span>Owner</span><span>Status</span></div><div class="po-axis">${ticks.map(d=>`<span>${esc(d)}</span>`).join('')}</div></div>${chart||'<p class="po-empty">No tasks yet. Add a task to begin planning.</p>'}${m.checkpoints.length?`<div class="po-plan-row po-milestone-head"><strong>Key milestones</strong><span></span></div>${m.checkpoints.map(item=>`<div class="po-plan-row"><button class="po-milestone-label text-btn" data-milestone-edit="${esc(item.id)}">◆ ${esc(item.name)} <small>${date(item.date)}</small></button><div class="po-track"><button class="po-diamond" style="left:${left(item.date)}%" data-milestone-edit="${esc(item.id)}" aria-label="Edit milestone ${esc(item.name)}">◆</button></div></div>`).join('')}`:''}<div class="po-chart-foot">${date(Planning.iso(start))} — ${date(Planning.iso(end))} · Dashed line: Today · Click a task or milestone to edit</div></div></div></section></div><div class="po-right"><section class="panel"><h2>Project Progress</h2><div class="po-progress-chart"><div class="po-donut" style="background:conic-gradient(${stops||'#e3ebf5 0% 100%'})"><span><b>${m.progress}%</b><small>Complete</small></span></div><div class="po-legend">${m.counts.map(c=>`<div><i style="background:${colors[c.status]}"></i><span>${esc(c.status)}</span><b>${c.count}</b></div>`).join('')}</div></div></section><section class="panel"><div class="po-panel-heading"><h2>Key Milestones</h2><button class="text-btn" data-project-milestone="${esc(p.id)}">+ Add</button></div><div class="po-milestones">${m.checkpoints.map(item=>`<button data-milestone-edit="${esc(item.id)}"><i class="${item.status==='Completed'?'done':''}">${item.status==='Completed'?'✓':'◇'}</i><span>${esc(item.name)}<small>${esc(item.date)}</small></span></button>`).join('')||'<p class="po-empty">No milestones yet.</p>'}</div></section><section class="panel"><div class="po-panel-heading"><h2>Team</h2><button class="text-btn" data-po-team="${esc(p.id)}">Team Map</button></div><div class="po-people">${m.people.map(member=>`<div>${avatar(member)}<button class="text-btn" data-member-profile="${esc(member.id)}">${esc(member.name)}<small>${esc(member.id===p.managerId?'Project Manager':member.role||'Project contributor')}</small></button></div>`).join('')||'<p class="po-empty">No contributors yet.</p>'}</div></section></div></div>`;
 }
 return {render};
})();
